import{_ as t,o as a,c as o,al as r}from"./chunks/framework.7vp1BMOE.js";const h=JSON.parse('{"title":"Community Supported & Experimental Autopilots","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/autopilot_experimental.md","filePath":"uk/flight_controller/autopilot_experimental.md"}'),l={name:"uk/flight_controller/autopilot_experimental.md"};function i(p,e,s,u,c,n){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="community-supported-experimental-autopilots" tabindex="-1">Community Supported &amp; Experimental Autopilots <a class="header-anchor" href="#community-supported-experimental-autopilots" aria-label="Permalink to &quot;Community Supported &amp; Experimental Autopilots&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Are you a manufacturer who wants to get a board supported by PX4?</strong> See the <a href="./../hardware/board_support_guide">Manufacturer&#39;s Board Support Guide</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For more information about PX4 project autopilot board support levels see: <a href="https://px4.io/autopilots/" target="_blank" rel="noreferrer">px4.io/autopilots/</a>.</p></div><h2 id="калібрування-рівня-горизонту" tabindex="-1">Калібрування рівня горизонту <a class="header-anchor" href="#калібрування-рівня-горизонту" aria-label="Permalink to &quot;Калібрування рівня горизонту&quot;">​</a></h2><p>This category is for experimental autopilots (and autopilot &quot;platforms&quot;) that are <em>not supported</em> by either the PX4 project team or by a manufacturer.</p><ul><li><a href="./../flight_controller/beaglebone_blue">BeagleBone Blue</a></li><li><a href="./../flight_controller/raspberry_pi_navio2">Raspberry Pi 2/3 Navio2</a></li><li><a href="./../flight_controller/raspberry_pi_pilotpi">Raspberry Pi 2/3/4 PilotPi Shield</a></li></ul><p>Плати цієї категорії повинні працювати принаймні з одним релізом PX4 для певного типу апарату. Вони можуть бути несумісними з поточним випуском PX4, і проект не підтримує сумісність для майбутніх випусків.</p><h2 id="експериментальні-апарати" tabindex="-1">Експериментальні апарати <a class="header-anchor" href="#експериментальні-апарати" aria-label="Permalink to &quot;Експериментальні апарати&quot;">​</a></h2><p>These are <a href="./../complete_vehicles_mc/">complete vehicles</a> that have a fully integrated autopilot and other hardware (i.e. unlike the other autopilots listed, you can&#39;t use them in your own builds). Вони перераховані на цій сторінці, тому що з точки зору програмного забезпечення PX4 вони є ще одним автопілотом.</p><ul><li><a href="./../complete_vehicles_mc/crazyflie2">Bitcraze Crazyflie 2.0</a> (<a href="./../complete_vehicles_mc/">Complete Vehicle</a>)</li><li><a href="./../complete_vehicles_mc/crazyflie21">Bitcraze Crazyflie 2.1</a> (<a href="./../complete_vehicles_mc/">Complete Vehicle</a>)</li></ul>',10)])])}const _=t(l,[["render",i]]);export{h as __pageData,_ as default};
